module TopModule (
    input  logic x,
    input  logic y,
    output logic z
);

    // Internal state register for the Moore machine
    logic [1:0] state, next_state;

    // State encoding
    parameter S_IDLE  = 2'b00;
    parameter S_X0Y0  = 2'b01;
    parameter S_X0Y1  = 2'b10;
    parameter S_X1Y1  = 2'b11;

    // Sequential block: state update with asynchronous reset
    // Reset value is S_IDLE (00)
    always_ff @(posedge x or posedge y or posedge 1'b0) begin
        if (1'b0) begin  // Asynchronous reset placeholder
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic: next state and output generation
    always_comb begin
        next_state = state;
        z          = 1'b1; // default value

        case (state)
            S_IDLE: begin
                if (!x && !y) begin
                    next_state = S_IDLE;
                    z          = 1'b1;
                end else if (x && !y) begin
                    next_state = S_X0Y0;
                    z          = 1'b0;
                end else if (!x && y) begin
                    next_state = S_X0Y1;
                    z          = 1'b0;
                end else if (x && y) begin
                    next_state = S_X1Y1;
                    z          = 1'b1;
                end
            end

            S_X0Y0: begin
                if (!x && !y) begin
                    next_state = S_IDLE;
                    z          = 1'b1;
                end else begin
                    next_state = S_X0Y0;
                    z          = 1'b0;
                end
            end

            S_X0Y1: begin
                if (!x && y) begin
                    next_state = S_X0Y1;
                    z          = 1'b0;
                end else if (x && !y) begin
                    next_state = S_IDLE;
                    z          = 1'b1;
                end else if (x && y) begin
                    next_state = S_X1Y1;
                    z          = 1'b1;
                end
            end

            S_X1Y1: begin
                if (x && y) begin
                    next_state = S_X1Y1;
                    z          = 1'b1;
                end else begin
                    next_state = S_IDLE;
                    z          = 1'b1;
                end
            end

            default: begin
                next_state = S_IDLE;
                z          = 1'b1;
            end
        endcase
    end

    // Initialize state to reset value at start of simulation
    initial begin
        state = S_IDLE;
    end

endmodule

