module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding for the FSM
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Datapath registers to hold the three bytes of the current message
    logic [7:0] byte1, byte2, byte3;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            IDLE: begin
                // Look for a byte with bit 3 set (in[3] == 1)
                if (in[3]) begin
                    next_state = BYTE1;
                end else begin
                    next_state = IDLE;
                end
            end
            BYTE1: begin
                // Received first byte, move to second
                next_state = BYTE2;
            end
            BYTE2: begin
                // Received second byte, move to third
                next_state = BYTE3;
            end
            BYTE3: begin
                // Received third byte, signal done and return to IDLE
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // State flip-flons with synchronous reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= IDLE;
            byte1       <= 8'b0;
            byte2       <= 8'b0;
            byte3       <= 8'b0;
            done        <= 1'b0;
        end else begin
            state       <= next_state;

            case (state)
                IDLE: begin
                    // In IDLE we do not capture data unless we detect byte 1
                    // done is cleared (it will be asserted in the cycle after BYTE3)
                    done <= 1'b0;
                end
                BYTE1: begin
                    // Capture the first byte (the one that had in[3]=1)
                    byte1 <= in;
                    done  <= 1'b0;
                end
                BYTE2: begin
                    // Capture the second byte
                    byte2 <= in;
                    done  <= 1'b0;
                end
                BYTE3: begin
                    // Capture the third byte
                    byte3 <= in;
                    // out_bytes is assembled here; done will be asserted
                    // in the cycle after this one (per spec)
                    out_bytes <= {byte1, byte2, byte3};
                    done      <= 1'b1;
                end
                default: begin
                    done <= 1'b0;
                end
            endcase
        end
    end

    // Asynchronous reset handling: on the first clock edge after
    // reset is asserted, all state and outputs are initialized.
    // The above always_ff block already does this because reset is
    // in the sensitivity list and initializes everything.

endmodule

