module TopModule (
    input  logic [3:0] x,   // x[3], x[2], x[1], x[0]
    output logic       f
);

    // Internal signal for the K-map column order (x[1], x[2])
    // K-map columns: 00, 01, 11, 10  -> we map x[1], x[2] directly
    logic [1:0] kmap_cols;

    // Assign the two K-map select bits.
    // The specification lists x[1] and x[2] as the column select bits.
    // Fix: part-select must use ascending bit indices; x[2] is the high bit, x[1] is the low bit.
    assign kmap_cols = {x[2], x[1]};

    // Combinational logic implementing the function from the K-map.
    // K-map truth table (rows: x[3:4], columns: x[1:2] in order 00,01,11,10):
    //   x[3:4]=00: d, 0, d, d
    //   x[3:4]=01: 0, d, 1, 0
    //   x[3:4]=11: 1, 1, d, d
    //   x[3:4]=10: 1, 1, 0, d
    //
    // Derived minimal SOP expression (don't-cares used to simplify):
    //   f = (x[3] & x[4]) |
    //       (!x[3] & !x[4] & !x[1]) |
    //       (!x[3] &  x[4] &  x[1] &  x[2]) |
    //       ( x[3] & !x[4] &  x[1])
    //
    // This expression covers all specified 1s and uses don't-cares to
    // eliminate hazards and reduce gate count.

    always_comb begin
        case ({x[3], x[4]})
            2'b00: f = 1'b0;           // row 00: don't-cares and 0 -> force 0
            2'b01: f = (!x[1] &  x[2]) | (!x[1] & !x[2]); // row 01: 0, d, 1, 0 -> simplifies to !x[1]
            2'b11: f = (x[1] &  x[2]) | (x[1] & !x[2]);    // row 11: 1, 1, d, d -> x[1]
            2'b10: f = (x[1] &  x[2]) | (!x[1] &  x[2]) | (!x[1] & !x[2]); // row 10: 1, 1, 0, d -> simplifies to x[2]
            default: f = 1'b0;
        endcase
    end

endmodule

