module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 0=idle, 1=seen_first_1, 2=seen_11, 3=seen_110
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        S1     = 2'b01,
        S2     = 2'b10,
        S3     = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            IDLE:    next_state = (data == 1'b1) ? S1 : IDLE;
            S1:      next_state = (data == 1'b1) ? S2 : IDLE;
            S2:      next_state = (data == 1'b0) ? S3 : IDLE;
            S3:      next_state = (data == 1'b1) ? IDLE : S3;
            default: next_state = IDLE;
        endcase
    end

    // Output logic & state flip-flops with synchronous reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // start_shifting asserted when we have detected the full sequence 1101.
    // The sequence completes at the moment we transition from S3 to IDLE on a '1'.
    // We assert start_shifting when we are in S3 and data is 1 (i.e., the 4th bit arrives).
    assign start_shifting = (state == S3) & (data == 1'b1) ? 1'b1 : 1'b0;

endmodule

Prob155_lemmings4.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT   = 3'b000,
        WALK_RIGHT  = 3'b001,
        FALLING     = 3'b010,
        DIGGING     = 3'b011,
        SPLATTERED  = 3'b100
    } state_t;

    // State registers
    state_t state, next_state;

    // Register to remember walking direction before falling
    logic fell_from_left;

    // Output logic (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // Fall counter for splatter detection
    logic [4:0] fall_count; // 5 bits enough for >20

    // Next-state logic (combinational)
    always_comb begin
        next_state = state; // default: stay in current state

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall if ground disappears
                    next_state = FALLING;
                    // Capture the direction we are leaving
                    fell_from_left <= 1'b1;
                end else if (dig && !bump_left && !bump_right) begin
                    // Dig if told to dig and not bumped (bump has no effect while digging)
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction if bumped
                    if (bump_left && !bump_right)
                        next_state = WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_LEFT;
                    else
                        // Bumped on both sides - still switch
                        next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    fell_from_left <= 1'b0;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    if (bump_right && !bump_left)
                        next_state = WALK_LEFT;
                    else if (bump_left && !bump_right)
                        next_state = WALK_RIGHT;
                    else
                        next_state = (state == WALK_RIGHT) ? WALK_LEFT : WALK_RIGHT;
                end
            end

            FALLING: begin
                if (!ground) begin
                    // Stay falling
                    next_state = FALLING;
                end else begin
                    // Ground reappeared
                    if (fall_count > 20) begin
                        // Splatter: fell for more than 20 cycles
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in original direction
                        if (fell_from_left)
                            next_state = WALK_LEFT;
                        else
                            next_state = WALK_RIGHT;
                    end
                end
            end

            DIGGING: begin
                // Can only dig on ground
                if (!ground) begin
                    // Start falling when digging reaches ground=0
                    next_state = FALLING;
                    // Preserve direction before fall
                    // Direction is already captured in fell_from_left from previous state
                end else if (dig) begin
                    // Continue digging
                    next_state = DIGGING;
                end else begin
                    // Stop digging, resume walking in current direction
                    next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
                end
                // Being bumped while digging has no effect
            end

            SPLATTERED: next_state = SPLATTERED;
        endcase
    end

    // Sequential block with reset and fall counter
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_count <= 0;
            fell_from_left <= 1'b0;
        end else begin
            state <= next_state;
            // Increment fall counter each cycle while in FALLING state
            if (state == FALLING) begin
                if (fall_count < 31)
                    fall_count <= fall_count + 1'b1;
                else
                    fall_count <= fall_count;
            end else begin
                // Reset counter when not falling (walking, digging, splattered)
                fall_count <= 0;
            end
        end
    end

endmodule

