    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // State register (synchronous positive-edge triggered with async active-high reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

