module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state: 2-bit state machine
    // 00: below s[0] (all outputs high)
    // 01: between s[1] and s[0] (fr0, fr1)
    // 10: between s[2] and s[1] (fr0)
    // 11: above s[2] (no flow)
    reg [1:0] state;
    reg [1:0] prev_state;   // level previous to the last sensor change

    // Assign outputs based on current state and previous state
    // dfr logic: if current level (state) is higher than previous level (prev_state), open supplemental valve (dfr=1)
    // If current level is lower, close it (dfr=0). If equal, hold value.
    // Reset sets dfr=1 (all outputs high).
    assign fr0 = (state == 2'b00) ? 1'b1 :
                 (state == 2'b01) ? 1'b0 :
                 (state == 2'b10) ? 1'b0 :
                 (state == 2'b11) ? 1'b1 : 1'b1;

    assign fr1 = (state == 2'b00) ? 1'b1 :
                 (state == 2'b01) ? 1'b0 :
                 (state == 2'b10) ? 1'b1 :
                 (state == 2'b11) ? 1'b1 : 1'b1;

    assign fr2 = (state == 2'b00) ? 1'b1 :
                 (state == 2'b01) ? 1'b1 :
                 (state == 2'b10) ? 1'b1 :
                 (state == 2'b11) ? 1'b1 : 1'b1;

    assign dfr = (state > prev_state) ? 1'b1 :
                 (state < prev_state) ? 1'b0 :
                 1'b1; // hold or default to 1 on reset/equal

    // Sequential block for state update and prev_state tracking
    // Active-high synchronous reset. Reset state is equivalent to water level low for long time.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset state: below s[0] (00), all outputs high (fr0=1, fr1=1, fr2=1, dfr=1)
            state <= 2'b00;
            prev_state <= 2'b00;
        end else begin
            // Update state based on current sensor inputs s[2:0]
            // Priority: above s[2] > between s[2]-s[1] > between s[1]-s[0] > below s[0]
            if (s[2]) begin
                state <= 2'b11; // above s[2]
            end else if (s[1]) begin
                state <= 2'b10; // between s[2] and s[1]
            end else if (s[0]) begin
                state <= 2'b01; // between s[1] and s[0]
            end else begin
                state <= 2'b00; // below s[0]
            end
            // Track previous state for dfr comparison on next cycle
            prev_state <= state;
        end
    end

endmodule

